function shipCard(doc2, data, state, actions) {
  const card2 = element(doc2, "article", "card");
  card2.appendChild(element(doc2, "p", "operation", "Build and publish"));
  const runs = element(doc2, "div", "row-actions");
  const verify = button(doc2, state.verify === "running" ? "cta cta-busy" : state.verify === "passed" ? "cta cta-done" : "cta cta-lead", RUN_LABELS[state.verify].verify, () => actions.verify());
  if (state.verify === "running") {
    verify.setAttribute("disabled", "true");
  }
  runs.appendChild(verify);
  const build = button(doc2, state.build === "running" ? "cta cta-busy" : state.build === "passed" ? "cta cta-done" : "cta", RUN_LABELS[state.build].build, () => actions.build());
  if (state.build === "running") {
    build.setAttribute("disabled", "true");
  }
  runs.appendChild(build);
  card2.appendChild(runs);
  for (const archive of data.built) {
    const row = element(doc2, "div", "inside-row");
    row.appendChild(element(doc2, "span", "inside-name", `dist/${archive.file}`));
    row.appendChild(element(doc2, "span", "inside-detail", archive.size));
    card2.appendChild(row);
  }
  if (data.built.length === 0) {
    card2.appendChild(element(doc2, "p", "empty", "Nothing built yet."));
  }
  card2.appendChild(element(doc2, "p", "foot-note", "Publishing runs from the CLI: facet publish, or the /facet-publish command. This server has no publish tool, because a published version can never be replaced."));
  return card2;
}

